package com.eventpulse.service;
import com.eventpulse.model.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class ReminderServiceTest {@Test void sendsOnlyWhenReminderIsDueAndEventStillUpcoming(){var events=mock(EventService.class);var notifications=mock(NotificationService.class);var e=new Event();e.setEventId("e");e.setStatus("UPCOMING");e.setStartDateTime("2027-01-02T08:00:00Z");when(events.get("e")).thenReturn(e);var accepted=new NotificationRecord();accepted.setStatus("ACCEPTED_BY_SES");when(notifications.announce(eq(e),eq(NotificationService.EVENT_REMINDER),anyString())).thenReturn(List.of(accepted));var service=new ReminderService(events,notifications,Clock.fixed(Instant.parse("2027-01-01T09:00:00Z"),ZoneOffset.UTC));assertEquals(1,service.sendReminder("e","24h"));assertEquals(0,service.sendReminder("e","1h"));verify(notifications,times(1)).announce(eq(e),eq(NotificationService.EVENT_REMINDER),anyString());}
 @Test void doesNotSendForCancelledEvent(){var events=mock(EventService.class);var notifications=mock(NotificationService.class);var e=new Event();e.setStatus("CANCELLED");e.setStartDateTime("2027-01-02T08:00:00Z");when(events.get("e")).thenReturn(e);var service=new ReminderService(events,notifications,Clock.fixed(Instant.parse("2027-01-01T00:00:00Z"),ZoneOffset.UTC));assertEquals(0,service.sendReminder("e","24h"));verifyNoInteractions(notifications);}}
